def holm(pvalues, alpha=0.05):
    items = sorted(pvalues.items(), key=lambda kv: (kv[1], kv[0]))
    m = len(items)
    rejected = []
    for i, (name, p) in enumerate(items):
        if p <= alpha / (m - i):
            rejected.append(name)
        else:
            break
    return sorted(rejected)
